using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using TMPro;
public static class InspectCurrentStreet{public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling)throw new Exception("Idle required");for(int i=0;i<SceneManager.sceneCount;i++)if(SceneManager.GetSceneAt(i).isDirty)throw new Exception("Dirty scene");var setup=EditorSceneManager.GetSceneManagerSetup();try{EditorSceneManager.OpenScene("Assets/ShooterSurvival/Scenes/Tools/Jamsil.unity");var d=UnityEngine.Object.FindFirstObjectByType<Chapter45Director>();return new{d.chapter,route=d.route.Length,encounters=d.encounters.Select(e=>new{e.name,e.floor,e.activationDistance,e.stopDistance,e.requiredToProceed,e.choiceIndex,e.requiredChoice,e.health,e.damage,actors=e.actors.Select(a=>new{a.name,position=a.transform.position.ToString(),model=a.GetComponentsInChildren<Animator>(true).Select(x=>AssetDatabase.GetAssetPath(x.avatar)).ToArray()}).ToArray()}).ToArray(),hazards=d.hazards.Select(h=>new{h.name,h.distance,h.choiceIndex,h.requiredChoice,body=h.body==null?null:h.body.name,sweepFrom=h.sweepFrom.ToString(),sweepTo=h.sweepTo.ToString()}).ToArray(),choices=d.choices.Select(c=>new{c.name,kind=c.kind.ToString(),c.distance,c.endDistance,c.rewardDistance,c.branchOffset,c.leftName,c.rightName,c.riskAttackPercent}).ToArray(),targets=d.targets.Select(t=>new{t.name,t.distance,t.floor}).ToArray(),signs=d.GetComponentsInChildren<TMP_Text>(true).Where(t=>t.name.Contains("Sign")||t.name.Contains("Store")||t.name.Contains("Label")).Take(90).Select(t=>new{t.name,t.text,path=Path(t.transform)}).ToArray()};}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}}static string Path(Transform t)=>t.parent==null?t.name:Path(t.parent)+"/"+t.name;}
